method SumEvenAtOddIndices(lst: seq<int>) returns (sum: int)
    decreases |lst|
    {
        if |lst| == 0 {
            return 0;
        }
        var firstElem := lst[0];
        var rest := lst[1..];
        if |rest| == 0 {
            return 0; // No elements left to process
        }

        var secondElem := rest[0];
        var further := rest[1..];
        var evenAtOddIndex := if (secondElem % 2 == 0) then secondElem else 0;

        return evenAtOddIndex + SumEvenAtOddIndices(further);
    }
